 [CmdletBinding()]
 param(
     [Parameter(Position = 0)]
     [string]$Command = 'help',

     [Parameter(Position = 1, ValueFromRemainingArguments)]
     [string[]]$CliArguments = @()
 )

 Set-StrictMode -Version Latest
 $ErrorActionPreference = 'Stop'
 Import-Module (Join-Path $PSScriptRoot 'TaskForge.Core.psm1') -Force -WarningAction SilentlyContinue

 try {
     $defaultDataFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'data/tasks.json'
     $defaultConfigFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'config/taskforge.config.json'
     $bannerFile = Join-Path (Split-Path -Parent $PSScriptRoot) 'assets/config.txt'

     if ($Command.ToLowerInvariant() -eq 'config') {
         if ($CliArguments.Count -eq 0) {
             throw 'config requires an action: set, get, or list.'
         }
         $action = $CliArguments[0]
         if ($action.StartsWith('--')) {
             throw 'config requires an action: set, get, or list.'
         }
         $rest = if ($CliArguments.Count -gt 1) { $CliArguments[1..($CliArguments.Count - 1)] } else { @() }
         $cfgOptions = ConvertFrom-TaskForgeArguments -Arguments $rest
         $configFile = if ($cfgOptions.Contains('config-file')) {
             Get-RequiredOption -Options $cfgOptions -Name 'config-file'
         }
         else {
             $defaultConfigFile
         }

         switch ($action.ToLowerInvariant()) {
             'set' {
                 Assert-KnownOptions -Options $cfgOptions -Allowed @('key', 'value', 'config-file')
                 $key = Get-RequiredOption -Options $cfgOptions -Name 'key'
                 $value = Get-RequiredOption -Options $cfgOptions -Name 'value'
                 $config = Read-ConfigStore -Path $configFile
                 $config = Set-ConfigValue -Config $config -Key $key -Value $value
                 Write-ConfigStore -Path $configFile -Config $config
                 "Set $key = $($config[$key])"
             }
             'get' {
                 Assert-KnownOptions -Options $cfgOptions -Allowed @('key', 'config-file', 'json')
                 $key = Get-RequiredOption -Options $cfgOptions -Name 'key'
                 Assert-KnownConfigKey -Key $key
                 $config = Read-ConfigStore -Path $configFile
                 $value = if ($config.Contains($key)) { $config[$key] } else { $null }
                 if ($cfgOptions.Contains('json')) {
                     Write-TaskForgeOutput -Value ([pscustomobject]@{ key = $key; value = $value }) -AsJson $true
                 }
                 elseif ($null -eq $value) {
                     ''
                 }
                 else {
                     [string]$value
                 }
             }
             'list' {
                 Assert-KnownOptions -Options $cfgOptions -Allowed @('config-file', 'json')
                 $config = Read-ConfigStore -Path $configFile
                 if ($cfgOptions.Contains('json')) {
                     $ordered = [ordered]@{}
                     foreach ($name in Get-ConfigKeys) {
                         if ($config.Contains($name)) { $ordered[$name] = $config[$name] }
                     }
                     Write-TaskForgeOutput -Value ([pscustomobject]$ordered) -AsJson $true
                 }
                 else {
                     $lines = [System.Collections.Generic.List[string]]::new()
                     if (Test-Path -LiteralPath $bannerFile) {
                         $banner = (Get-Content -LiteralPath $bannerFile -Raw).TrimEnd("`r", "`n")
                         $lines.Add($banner)
                     }
                     $settings = foreach ($name in Get-ConfigKeys) {
                         if ($config.Contains($name)) { "{0} = {1}" -f $name, $config[$name] }
                     }
                     if (@($settings).Count -eq 0) {
                         $lines.Add('No configuration.')
                     }
                     else {
                         $settings | ForEach-Object { $lines.Add($_) }
                     }
                     $lines -join "`n"
                 }
             }
             default {
                 throw "Unknown config action: $action"
             }
         }
         exit 0
     }

     $options = ConvertFrom-TaskForgeArguments -Arguments $CliArguments
